test:
class PickFirst:
    def choice(self, sequence):
        return list(sequence)[0]

class PickLast:
    def choice(self, sequence):
        return list(sequence)[-1]

corpus = 'a b a c a b a c a'
first = generate_sentence(corpus, 4, PickFirst())
last = generate_sentence(corpus, 4, PickLast())
assert first != last
assert len(first.split()) == len(last.split()) == 4
print('ok')

class PickLast:
    def choice(self, sequence):
        return list(sequence)[-1]

assert generate_sentence('red blue green red', 1, PickLast()) == 'red'
print('ok')
